def _resolve_pointer(doc: Any, pointer: str) -> Any:
    if not pointer:
        return doc
    cur = doc
    for seg in pointer.split("/")[1:]:
        key = seg.replace("~1", "/").replace("~0", "~")
        if isinstance(cur, dict):
            cur = cur[key]
        elif (
            isinstance(cur, list)
            and key.isascii()
            and key.isdecimal()
            and (key == "0" or not key.startswith("0"))
        ):
            cur = cur[int(key)]
        else:
            raise KeyError(key)
    return cur


def evaluate_artifact_guard(
    guard: VerifiedArtifactGuard, accepted_outputs: dict[str, dict[str, Any]]
) -> bool:
    """Deterministically evaluate a model-free guard over accepted step outputs."""
    step_out = accepted_outputs.get(guard.step)
    if step_out is None or guard.output not in step_out:
        return False
    try:
        actual = _resolve_pointer(step_out[guard.output], guard.pointer)
    except (KeyError, IndexError, TypeError):
        return False
    if guard.op == "is_present":
        return actual is not None
    if guard.op == "eq":
        return (
            actual == guard.value
            and type(actual) is type(guard.value)
            or (
                type(actual) in (int, float)
                and type(guard.value) in (int, float)
                and actual == guard.value
            )
        )
    if guard.op == "ne":
        return not evaluate_artifact_guard(
            guard.model_copy(update={"op": "eq"}), accepted_outputs
        )
    if guard.op == "in_set":
        return any(
            actual == item
            and (
                type(actual) is type(item)
                or (type(actual) in (int, float) and type(item) in (int, float))
            )
            for item in (guard.value or ())
        )
    if (
        type(actual) not in (int, float)
        or type(actual) is bool
        or not math.isfinite(actual)
    ):
        return False
    threshold = float(guard.value)
    if guard.op == "gt":
        return float(actual) > threshold
    if guard.op == "gte":
        return float(actual) >= threshold
    if guard.op == "lt":
        return float(actual) < threshold
    return float(actual) <= threshold


def evaluate_v0_checks(
    definition: FormalMethodDefinition,
    caller_values: dict[str, Any],
    outputs: dict[str, Any],
    *,
    authorized_materials: Collection[str] | None = None,
) -> tuple[V0CheckResult, ...]:
    """Run all deterministic V0 checks declared in Element 4 (how_to_validate)."""
    results: list[V0CheckResult] = []
    combined = {"inputs": caller_values, "outputs": outputs, **outputs}
    allowed_mats = (
        set(authorized_materials) if authorized_materials is not None else None
    )
    for rule in definition.how_to_validate:
        for idx, chk in enumerate(rule.v0_checks):
            passed = False
            detail = ""
            try:
                if isinstance(chk, NumericIdentityCheck):
                    lhs = _resolve_pointer(combined, chk.lhs_pointer)
                    rhs = _resolve_pointer(combined, chk.rhs_pointer)
                    if (
                        type(lhs) in (int, float)
                        and type(rhs) in (int, float)
                        and math.isfinite(lhs)
                        and math.isfinite(rhs)
                    ):
                        diff = abs(float(lhs) - float(rhs))
                        passed = diff <= chk.tolerance
                        detail = (
                            "numeric_identity_ok"
                            if passed
                            else f"abs_diff={diff} exceeds tolerance={chk.tolerance}"
                        )
                    else:
                        detail = "numeric_identity target is not a finite number"
                elif isinstance(chk, SchemaRangeCheck):
                    val = _resolve_pointer(outputs, chk.pointer)
                    passed = True
                    if chk.non_empty and val in (None, "", [], {}):
                        passed, detail = False, "value is empty"
                    elif chk.allowed_values and str(val) not in chk.allowed_values:
                        passed, detail = False, "value outside allowed_values"
                    elif type(val) in (int, float) and type(val) is not bool:
                        if chk.min_value is not None and float(val) < chk.min_value:
                            passed, detail = False, f"value < min_value {chk.min_value}"
                        elif chk.max_value is not None and float(val) > chk.max_value:
                            passed, detail = False, f"value > max_value {chk.max_value}"
                    if passed:
                        detail = "schema_and_range_ok"
                elif isinstance(chk, SourcedCitationCheck):
                    val = _resolve_pointer(outputs, chk.pointer)
                    citations = val.get("citations") if isinstance(val, dict) else val
                    if not isinstance(citations, list) or not citations:
                        detail = "citations list is empty"
                    else:
                        valid_cites = True
                        expected_mats = allowed_mats
                        if (
                            chk.material_input_slot
                            and chk.material_input_slot in caller_values
                        ):
                            raw_in = caller_values[chk.material_input_slot]
                            slot_mats = (
                                {str(x) for x in raw_in}
                                if isinstance(raw_in, list)
                                else {str(raw_in)}
                            )
                            expected_mats = (
                                slot_mats & expected_mats
                                if expected_mats is not None
                                else slot_mats
                            )
                        for c in citations:
                            mid = c.get("material_id") if isinstance(c, dict) else None
                            loc = c.get("locator") if isinstance(c, dict) else None
                            if not mid or not loc:
                                valid_cites = False
                                detail = "citation missing material_id or locator"
                                break
                            if (
                                expected_mats is not None
                                and str(mid) not in expected_mats
                            ):
                                valid_cites = False
                                detail = f"unauthorized citation material_id={mid}"
                                break
                        passed = valid_cites
                        if passed:
                            detail = "sourced_citation_ok"
                elif isinstance(chk, CollectionCoverageCheck):
                    rows = _resolve_pointer(outputs, chk.items_pointer)
                    expected_raw = caller_values.get(chk.expected_keys_input_slot)
                    if not isinstance(rows, list) or not isinstance(expected_raw, list):
                        detail = "items or expected_keys is not a list"
                    else:
                        got_keys = [
                            r.get(chk.key_field)
                            for r in rows
                            if isinstance(r, dict) and chk.key_field in r
                        ]
                        exp_set = {str(x) for x in expected_raw}
                        got_strs = [str(k) for k in got_keys]
                        passed = (
                            len(got_strs) == len(rows)
                            and len(set(got_strs)) == len(got_strs)
                            and set(got_strs) == exp_set
                        )
                        detail = (
                            "collection_coverage_ok"
                            if passed
                            else "output keys do not match expected unique key set"
                        )
                elif isinstance(chk, ProhibitedTermsCheck):
                    val = _resolve_pointer(outputs, chk.pointer)
                    text_blob = (
                        val
                        if isinstance(val, str)
                        else json.dumps(val, ensure_ascii=False)
                    )
                    banned = (*DEFAULT_PROHIBITED_TERMS, *chk.extra_terms)
                    hit = [term for term in banned if term and term in text_blob]
                    passed = len(hit) == 0
                    detail = (
                        "prohibited_terms_ok"
                        if passed
                        else "prohibited terms found: " + ", ".join(hit)
                    )
            except (KeyError, IndexError, TypeError, ValueError) as exc:
                passed, detail = False, f"v0 pointer error: {exc}"
            results.append(
                V0CheckResult(
                    promise_id=rule.promise_id,
                    check_index=idx,
                    kind=chk.kind,
                    passed=passed,
                    detail=detail,
                )
            )
    return tuple(results)


def single_review_edge(
    procedure: Orchestration | ToolProcedure,
) -> tuple[str, str] | None:
    """A producer and one independent reviewer of its outputs in a DAG."""
    if not isinstance(procedure, Orchestration):
        return None
    for step in procedure.steps:
        if isinstance(step, ReviewPhaseStep) and step.phase == "comparison":
            return step.producer, step.role
    roles = procedure.collaboration or {}
    for reviewer in procedure.steps:
        role = roles.get(reviewer.id)
        if not role or len(role.review_requirements) != 1:
            continue
        producer, requirement = next(iter(role.review_requirements.items()))
        source_role = roles.get(producer)
        step_bindings = [
            i.binding
            for i in reviewer.inputs.values()
            if isinstance(i.binding, StepValue)
        ]
        if (
            requirement in ("isolated_reviewer", "different_model_family")
            and producer in reviewer.depends_on
            and set(role.handoff_from) <= {producer}
            and (
                not source_role
                or not (
                    source_role.review_requirements
                    or source_role.handoff_from
                    or source_role.comparison
                )
            )
            and step_bindings
            and all(b.step == producer for b in step_bindings)
        ):
            return producer, reviewer.id
    return None


@dataclass(frozen=True)
class ReviewGroup:
    producers: tuple[str, ...]
    reviewer: str
    different_family_from: tuple[str, ...]

    @property
    def requirement(self):
        return (
            "different_model_family"
            if self.different_family_from
            else "isolated_reviewer"
        )


def review_group(procedure: Orchestration | ToolProcedure) -> ReviewGroup | None:
    if not isinstance(procedure, Orchestration) or not procedure.collaboration:
        return None
    roles = procedure.collaboration
    pair = single_review_edge(procedure)
    if pair:
        producer, reviewer = pair
        producers = (producer,)
    else:
        reviewers = [
            s
            for s in procedure.steps
            if s.id in roles and roles[s.id].review_requirements
        ]
        if len(reviewers) != 1:
            return None
        step = reviewers[0]
        reviewer = step.id
        producers = tuple(sorted(roles[reviewer].review_requirements.keys()))
        if len(producers) != 2:
            return None
        groups = {
            roles[sid].isolation_group for sid in (*producers, reviewer) if sid in roles
        }
        if None in groups or len(groups) != 3:
            return None
        expected = set(producers)
        step_bindings = [
            i.binding for i in step.inputs.values() if isinstance(i.binding, StepValue)
        ]
        if (
            roles[reviewer].comparison
            or not expected.issubset(step.depends_on)
            or set(roles[reviewer].handoff_from) != expected
            or not step_bindings
            or any(b.step not in expected for b in step_bindings)
        ):
            return None
    strong = tuple(
        p
        for p in producers
        if roles[reviewer].review_requirements[p] == "different_model_family"
    )
    return ReviewGroup(producers, reviewer, strong)


def _valid_leaf_contract(procedure: ToolProcedure) -> bool:
    implementation = procedure.implementation.kind
    turns = procedure.max_model_turns
    return (
        implementation
        in (
            "mcp",
            "a2a",
            "skill_script",
            "registered_script",
            "service_function",
        )
        and turns == 0
    ) or (
        implementation in ("skill_instruction", "registered_instruction") and turns == 1
    )


def expand_unique_plan(
    root_method_id: UUID,
    definition: FormalMethodDefinition,
    resolved: dict[tuple[UUID, int], FrozenMethod],
) -> ExpandedPlan:
    """Expand actual invocation instances, retaining each direct parent."""
    unique_plan(definition)
    compile_method(root_method_id, definition, resolved)
    total, leaves = 0, 0
    references: dict[tuple[UUID, int], MethodRef] = {}

    def visit(mid, current, path, ancestors):
        nonlocal total, leaves
        total += 1
        if mid in ancestors or len(ancestors) >= 16 or total > 1000:
            raise ValueError("Recursive plan cycle or global execution limit")
        if isinstance(current.procedure, ToolProcedure):
            if not _valid_leaf_contract(current.procedure):
                raise ValueError("Unsupported execution contract for a fixed plan leaf")
            leaves += 1
            if leaves > 100:
                raise ValueError("Recursive plan exceeds 100 actual tool leaf calls")
            return implementation_kind(current.procedure.kind), [], 1, 1, 0
        local = unique_plan(current)
        nodes = []
        direct_nodes: dict[str, PlanNode] = {}
        depth, expansions, steps = 1, 1, len(local)
        for step in local:
            ref = step.candidates[0]
            key = (ref.method_id, ref.version)
            child = resolved.get(key)
            if (
                child is None
                or child.reference != ref
                or child.definition.digest() != ref.digest
            ):
                raise ValueError("Missing or changed frozen recursive dependency")
            if key in references and references[key] != ref:
                raise ValueError("One method version cannot have two digests")
            references[key] = ref
            child_path = (*path, step.id)
            kind, descendants, child_depth, child_expansions, child_steps = visit(
                ref.method_id, child.definition, child_path, (*ancestors, mid)
            )
            node = PlanNode(child_path, path, step, ref, child.definition, kind)
            direct_nodes[step.id] = node
            nodes.append(node)
            nodes.extend(descendants)
            depth = max(depth, 1 + child_depth)
            expansions += child_expansions
            steps += child_steps
        p = current.procedure
        if p.collaboration:
            rg = review_group(p)
            if not rg:
                raise ValueError(
                    "Independent review requires a valid review_group topology"
                )
            # Reviewers and revision producers must be isolated instructions.
            must_be_instruction = {rg.reviewer}
            for step in local:
                if isinstance(step, ReviewPhaseStep) or (
                    step.id in p.collaboration
                    and p.collaboration[rg.reviewer].comparison is not None
                    and step.id in rg.producers
                ):
                    must_be_instruction.add(step.id)
            for sid in must_be_instruction:
                if sid in direct_nodes:
                    d_proc = direct_nodes[sid].definition.procedure
                    if not isinstance(
                        d_proc, ToolProcedure
                    ) or d_proc.implementation.kind not in (
                        "registered_instruction",
                        "skill_instruction",
                    ):
                        raise ValueError(
                            "Independent review requires fixed isolated instructions"
                        )
        if (
            depth > p.max_depth
            or expansions > p.max_expansions
            or steps > p.max_steps
            or steps > 1000
        ):
            raise ValueError("Recursive plan exceeds an ancestor's subtree limits")
        return (
            implementation_kind(p.kind),
            nodes,
            depth,
            expansions,
            steps,
        )

    kind, nodes, depth, expansions, steps = visit(root_method_id, definition, (), ())
    return ExpandedPlan(
        tuple(nodes),
        tuple(
            references[key]
            for key in sorted(references, key=lambda k: (str(k[0]), k[1]))
        ),
        kind,
        depth,
        expansions,
        steps,
    )


def verify_envelope_graph(
    root_method_id: UUID,
    definition: FormalMethodDefinition,
    resolved: dict[tuple[UUID, int], FrozenMethod],
) -> tuple[int, int, int]:
    """Statically verify worst-case depth, expansions and leaf count."""
    compile_method(root_method_id, definition, resolved)

    def subtree_bounds(
        mid: UUID, current: FormalMethodDefinition, ancestors: tuple[UUID, ...]
    ) -> tuple[int, int, int]:
        if mid in ancestors or len(ancestors) >= 16:
            raise ValueError("Recursive envelope cycle or global depth limit")
        if isinstance(current.procedure, ToolProcedure):
            if not _valid_leaf_contract(current.procedure):
                raise ValueError("Unsupported execution contract for an envelope leaf")
            return 1, 1, 1
        p = current.procedure
        max_d = 1
        total_exp = 1
        total_leaves = 0
        total_steps = 0
        for step in p.steps:
            mult = (
                step.step_batch.max_objects
                if step.step_batch is not None
                else (
                    p.object_batch.max_objects
                    if p.object_batch is not None
                    and any(
                        isinstance(i.binding, ObjectItem) for i in step.inputs.values()
                    )
                    else 1
                )
            )
            cand_d = cand_exp = cand_leaves = 0
            for ref in step.candidates:
                child = resolved.get((ref.method_id, ref.version))
                if child is None or child.reference != ref:
                    raise ValueError("Missing frozen dependency in envelope graph")
                cd, ce, cl = subtree_bounds(
                    ref.method_id, child.definition, (*ancestors, mid)
                )
                cand_d = max(cand_d, cd)
                cand_exp = max(cand_exp, ce)
                cand_leaves = max(cand_leaves, cl)
            max_d = max(max_d, 1 + cand_d)
            total_exp += mult * cand_exp
            total_leaves += mult * cand_leaves
            total_steps += mult
        if (
            max_d > p.max_depth
            or total_exp > p.max_expansions
            or total_steps > p.max_steps
            or total_exp > 1000
            or total_leaves > 100
        ):
            raise ValueError(
                "Envelope graph exceeds depth, expansion or 100 actual tool leaf calls"
            )
        return max_d, total_exp, total_leaves

    return subtree_bounds(root_method_id, definition, ())


class UnmatchedCandidate(ValueError):
    def __init__(self, slot: str):
        self.slot = slot
        super().__init__(f"No frozen candidate matches input {slot}")


class BatchItem(ObjectItem):
    """A runtime binding for one member of the confirmed list."""

    object_id: str


class BatchRows(ObjectRows):
    """Exact worker instances, in the caller's frozen list order."""

    members: tuple[tuple[str, str], ...]


class InvalidObjectList(ValueError):
    pass


def expand_batch(
    definition: FormalMethodDefinition, graph: Orchestration, values: dict
) -> FormalMethodDefinition:
    spec = graph.object_batch
    if spec is None and graph.has_step_batch:
        return expand_step_batches(definition, graph, values)
    assert spec is not None
    worker, port, template = next(
        (s, name, i)
        for s in graph.steps
        for name, i in s.inputs.items()
        if isinstance(i.binding, ObjectItem)
    )
    assert isinstance(template.binding, ObjectItem)
    manifest = values.get(template.binding.name)
    _json_object(values)
    if (
        not isinstance(manifest, list)
        or not 1 <= len(manifest) <= spec.max_objects
        or not all(
            isinstance(v, str) and v and template.slot.accepts(v) for v in manifest
        )
        or len(set(manifest)) != len(manifest)
    ):
        raise InvalidObjectList(f"Invalid object list: {template.binding.name}")
    collector = next(s for s in graph.steps if s.id != worker.id)
    instances = []
    members = []
    for obj in manifest:
        key = "obj_" + hashlib.sha256(obj.encode()).hexdigest()[:48]
        if key == collector.id or any(k == key for k, _ in members):
            raise InvalidObjectList("Object instance identifier conflict")
        binding = BatchItem(
            source="object_item", name=template.binding.name, object_id=obj
        )
        inputs = {
            **worker.inputs,
            port: template.model_copy(update={"binding": binding}),
        }
        instances.append(worker.model_copy(update={"id": key, "inputs": inputs}))
        members.append((key, obj))
    inputs = dict(collector.inputs)
    for name, item in inputs.items():
        if isinstance(item.binding, ObjectRows):
            rows = BatchRows(**item.binding.model_dump(), members=tuple(members))
            inputs[name] = item.model_copy(update={"binding": rows})
    instances.append(
        collector.model_copy(
            update={"depends_on": tuple(k for k, _ in members), "inputs": inputs}
        )
    )
    return definition.model_copy(
        update={"procedure": graph.model_copy(update={"steps": tuple(instances)})}
    )


def expand_step_batches(
    definition: FormalMethodDefinition, graph: Orchestration, values: dict
) -> FormalMethodDefinition:
    """Expand composable local step_batch workers inside a multi-step DAG."""
    _json_object(values)
    expanded_steps: list[MethodStep] = []
    worker_members: dict[str, tuple[tuple[str, str], ...]] = {}
    all_ids = {s.id for s in graph.steps}
    for step in graph.steps:
        if step.step_batch is None:
            expanded_steps.append(step)
            continue
        port, template = next(
            (name, i)
            for name, i in step.inputs.items()
            if isinstance(i.binding, ObjectItem)
        )
        assert isinstance(template.binding, ObjectItem)
        manifest = values.get(template.binding.name)
        if (
            not isinstance(manifest, list)
            or not 1 <= len(manifest) <= step.step_batch.max_objects
            or not all(
                isinstance(v, str) and v and template.slot.accepts(v) for v in manifest
            )
            or len(set(manifest)) != len(manifest)
        ):
            raise InvalidObjectList(f"Invalid object list: {template.binding.name}")
        members: list[tuple[str, str]] = []
        for obj in manifest:
            key = "obj_" + hashlib.sha256(f"{step.id}:{obj}".encode()).hexdigest()[:48]
            if key in all_ids or any(k == key for k, _ in members):
                raise InvalidObjectList("Object instance identifier conflict")
            all_ids.add(key)
            binding = BatchItem(
                source="object_item", name=template.binding.name, object_id=obj
            )
            inputs = {
                **step.inputs,
                port: template.model_copy(update={"binding": binding}),
            }
            expanded_steps.append(
                step.model_copy(
                    update={"id": key, "inputs": inputs, "step_batch": None}
                )
            )
            members.append((key, obj))
        worker_members[step.id] = tuple(members)

    rewired: list[MethodStep] = []
    for step in expanded_steps:
        deps = list(step.depends_on)
        changed = False
        new_inputs = dict(step.inputs)
        for wid, members in worker_members.items():
            if wid in deps:
                changed = True
                idx = deps.index(wid)
                deps[idx : idx + 1] = [k for k, _ in members]
        for name, item in new_inputs.items():
            if (
                isinstance(item.binding, ObjectRows)
                and item.binding.step in worker_members
            ):
                changed = True
                rows = BatchRows(
                    **item.binding.model_dump(),
                    members=worker_members[item.binding.step],
                )
                new_inputs[name] = item.model_copy(update={"binding": rows})
        rewired.append(
            step.model_copy(update={"depends_on": tuple(deps), "inputs": new_inputs})
            if changed
            else step
        )
    return definition.model_copy(
        update={"procedure": graph.model_copy(update={"steps": tuple(rewired)})}
    )


def review_stage_id(role, phase):
    return "review_" + hashlib.sha256(f"{phase}:{role}".encode()).hexdigest()[:24]


def strict_plan(definition, graph, edge, revisions=0):
    producer, role = edge
    policy = graph.collaboration[role].comparison
    if not 0 <= revisions <= policy.max_reworks:
        raise ValueError("Review revisions exceed the frozen comparison policy")
    reviewer = next(s for s in graph.steps if s.id == role)
    source = next(s for s in graph.steps if s.id == producer)
    blind_template = review_stage_id(role, "blind")
    phases = [source]
    previous = None
    prior_submission = source

    def phase(template, logical_role, id_, kind, inputs, deps, producer_id, iteration):
        raw = logical_role.model_dump(by_alias=True)
        raw.update(
            id=id_,
            phase=kind,
            iteration=iteration,
            template=template,
            declared_inputs=logical_role.inputs,
            role=logical_role.id,
            producer=producer_id,
            predecessors=deps,
            depends_on=deps,
            inputs=inputs,
        )
        return ReviewPhaseStep.model_validate(raw)

    def add_outputs(inputs, prior, prefix):
        for name, slot in prior.outputs.items():
            key = (
                prefix + name
                if len(prefix + name) <= 64
                else review_stage_id(name, prefix)
            )
            if key in inputs:
                raise ValueError("Review handoff collides with a declared input")
            inputs[key] = StepInput(
                slot=slot, binding=StepValue(source="step", step=prior.id, output=name)
            )

    extra_reviewer_deps = tuple(d for d in reviewer.depends_on if d != producer)
    for iteration in range(revisions + 1):
        producer_id = producer
        if previous is not None:
            producer_id = review_stage_id(producer, f"revision{iteration}")
            inputs = dict(source.inputs)
            add_outputs(inputs, prior_submission, "prior_")
            add_outputs(inputs, previous, "feedback_")
            rev_deps = tuple(
                dict.fromkeys((*source.depends_on, prior_submission.id, previous.id))
            )
            prior_submission = phase(
                producer,
                source,
                producer_id,
                "revision",
                inputs,
                rev_deps,
                producer_id,
                iteration,
            )
            phases.append(prior_submission)
        inputs = {
            name: (
                item.model_copy(
                    update={
                        "binding": item.binding.model_copy(update={"step": producer_id})
                    }
                )
                if isinstance(item.binding, StepValue) and item.binding.step == producer
                else item
            )
            for name, item in reviewer.inputs.items()
        }
        blind_inputs = {
            k: v
            for k, v in inputs.items()
            if not (
                isinstance(v.binding, StepValue)
                and v.binding.step == producer_id
                and v.binding.output == policy.assessment_output
            )
        }
        if not blind_inputs:
            raise ValueError("Strict review needs distinct approved outputs")
        blind_id = (
            blind_template
            if not iteration
            else review_stage_id(role, f"blind{iteration}")
        )
        blind = phase(
            blind_template,
            reviewer,
            blind_id,
            "blind",
            blind_inputs,
            (*extra_reviewer_deps, producer_id),
            producer_id,
            iteration,
        )
        phases.append(blind)
        add_outputs(inputs, blind, "finding_")
        comparison_id = (
            role if not iteration else review_stage_id(role, f"comparison{iteration}")
        )
        previous = phase(
            role,
            reviewer,
            comparison_id,
            "comparison",
            inputs,
            (*extra_reviewer_deps, producer_id, blind_id),
            producer_id,
            iteration,
        )
        phases.append(previous)
    latest = {producer: producer_id, role: comparison_id}
    final_steps: list[MethodStep] = []
    inserted = False
    for step in graph.steps:
        if step.id == producer:
            continue
        if step.id == role:
            final_steps.extend(phases)
            inserted = True
            continue
        new_deps = tuple(dict.fromkeys(latest.get(d, d) for d in step.depends_on))
        new_in = {
            k: (
                v.model_copy(
                    update={
                        "binding": v.binding.model_copy(
                            update={"step": latest[v.binding.step]}
                        )
                    }
                )
                if isinstance(v.binding, StepValue) and v.binding.step in latest
                else v
            )
            for k, v in step.inputs.items()
        }
        final_steps.append(
            step.model_copy(update={"depends_on": new_deps, "inputs": new_in})
        )
    if not inserted:
        final_steps.extend(phases)
    if len({s.id for s in final_steps}) != len(final_steps):
        raise ValueError("Strict review step identity collision")
    exports = {
        k: ref.model_copy(update={"step": latest.get(ref.step, ref.step)})
        for k, ref in graph.exports.items()
    }
    return definition.model_copy(
        update={
            "procedure": graph.model_copy(
                update={"steps": tuple(final_steps), "exports": exports}
            )
        }
    )


def select_plan(
    definition: FormalMethodDefinition, values: dict, *, revisions: int = 0
) -> FormalMethodDefinition:
    """Derive a fixed invocation graph from the immutable rule and caller inputs."""
    graph = definition.procedure
    if not isinstance(graph, Orchestration):
        return definition
    current = definition
    if graph.has_candidate_choice:
        steps = []
        for step in graph.steps:
            choice = step.candidate_choice
            if choice is not None:
                port = step.inputs[choice.input]
                binding = port.binding
                if not isinstance(binding, CallerValue):
                    raise ValueError("Candidate selection requires a caller input")
                value = values.get(binding.name)
                selected = choice.match(value)
                if selected is None or not port.slot.accepts(value):
                    raise UnmatchedCandidate(binding.name)
                step = step.model_copy(
                    update={"candidates": (selected,), "candidate_choice": None}
                )
            steps.append(step)
        graph = graph.model_copy(update={"steps": tuple(steps)})
        current = current.model_copy(update={"procedure": graph})
    if graph.object_batch or graph.has_step_batch:
        current = expand_batch(current, graph, values)
        graph = current.procedure
        assert isinstance(graph, Orchestration)
    if graph.collaboration:
        edge = single_review_edge(graph)
        if (
            edge
            and graph.collaboration[edge[1]].comparison
            and not any(isinstance(s, ReviewPhaseStep) for s in graph.steps)
        ):
            current = strict_plan(current, graph, edge, revisions)
    return current


def unique_plan(definition: FormalMethodDefinition) -> tuple[MethodStep, ...]:
    """Stable topological order; textual descriptions do not act as conditions."""
    procedure = definition.procedure
    if not isinstance(procedure, Orchestration):
        raise ValueError("A unique plan requires an orchestration definition")
    if procedure.has_candidate_choice:
        raise ValueError("Runner lacks conditional candidate selection")
    if (procedure.object_batch or procedure.has_step_batch) and not any(
        isinstance(item.binding, BatchItem)
        for step in procedure.steps
        for item in step.inputs.values()
    ):
        raise ValueError("Runner lacks bounded object fanout")
    if procedure.max_replans != 0:
        raise ValueError("Unique plans cannot replan")
    if (
        procedure.max_depth < 2
        or len(procedure.steps) > procedure.max_steps
        or 1 + len(procedure.steps) > procedure.max_expansions
    ):
        raise ValueError("Unique plan exceeds its declared execution limits")
    references = {}
    for step in procedure.steps:
        if step.on_failure != "fail":
            raise ValueError("Unique plan execution requires fail-on-failure steps")
        if not step.always_required or len(step.candidates) != 1:
            raise ValueError(
                "Unique plans require every step and exactly one candidate"
            )
        if any(
            isinstance(item.binding, ResourceValue) for item in step.inputs.values()
        ):
            raise ValueError("Unique plans do not automatically bind resources")
        ref = step.candidates[0]
        key = (ref.method_id, ref.version)
        if key in references and references[key] != ref:
            raise ValueError("One method version cannot have two digests")
        references[key] = ref
    pending = {step.id: step for step in procedure.steps}
    done: dict[str, MethodStep] = {}
    while pending:
        ready = sorted(
            key for key, step in pending.items() if set(step.depends_on) <= done.keys()
        )
        if not ready:
            raise ValueError("Unique plan has an unknown dependency or cycle")
        key = ready[0]
        done[key] = pending.pop(key)
    return tuple(done.values())


def topological_envelope_steps(procedure: Orchestration) -> tuple[MethodStep, ...]:
    """Deterministic topological order over an envelope graph."""
    pending = {step.id: step for step in procedure.steps}
    done: dict[str, MethodStep] = {}
    while pending:
        ready = sorted(
            key for key, step in pending.items() if set(step.depends_on) <= done.keys()
        )
        if not ready:
            raise ValueError("Envelope graph has an unknown dependency or cycle")
        key = ready[0]
        done[key] = pending.pop(key)
    return tuple(done.values())


def _json_object(values: Any) -> dict:
    def visit(value, depth=0):
        if depth > 32:
            raise ValueError("Plan values exceed their depth limit")
        if type(value) is dict:
            for key, child in value.items():
                if type(key) is not str:
                    raise ValueError("Plan object keys must be strings")
                visit(child, depth + 1)
        elif type(value) is list:
            for child in value:
                visit(child, depth + 1)
        elif type(value) is float:
            if not math.isfinite(value):
                raise ValueError("Plan values must be finite JSON")
        elif value is not None and type(value) not in (str, int, bool):
            raise ValueError("Plan values must be JSON")

    if type(values) is not dict:
        raise ValueError("Plan values must be an object")
    visit(values)
    if len(json.dumps(values, ensure_ascii=False, allow_nan=False).encode()) > 64000:
        raise ValueError("Plan values exceed 64000 bytes")
    return values


def _validate_slots(slots: dict[str, ValueSlot], values: Any) -> dict:
    values = _json_object(values)
    if not values.keys() <= slots.keys():
        raise ValueError("Plan values name an undeclared slot")
    for name, slot in slots.items():
        if name not in values:
            if slot.required or slot.on_missing != "omit":
                raise ValueError(f"Missing plan value: {name}")
        elif not slot.accepts(values[name]):
            raise ValueError(f"Plan value does not match its schema: {name}")
    return copy.deepcopy(values)


def validate_plan_inputs(definition: FormalMethodDefinition, values: Any) -> dict:
    """Validate all external inputs before opening a child invocation."""
    if isinstance(definition.procedure, Orchestration) and not (
        definition.procedure.has_artifact_guard
        or definition.procedure.has_candidate_choice
        or definition.procedure.object_batch
        or definition.procedure.has_step_batch
    ):
        unique_plan(definition)
    slots = {
        name: ValueSlot.model_validate(item["slot"])
        for name, item in definition.interfaces()["inputs"].items()
    }
    return _validate_slots(slots, values)


def bind_step_inputs(
    step: MethodStep,
    caller_values: dict,
    accepted_outputs: dict[str, dict],
    *,
    skipped_steps: Collection[str] = (),
) -> dict:
    """Copy declared bindings; apply closed lenses and CollectPack."""
    _json_object(caller_values)
    skipped = set(skipped_steps)
    missing_deps = set(step.depends_on) - accepted_outputs.keys() - skipped
    if missing_deps:
        raise ValueError("A required predecessor has no accepted outputs")
    values = {}
    for name, item in step.inputs.items():
        binding = item.binding
        if isinstance(binding, BatchItem):
            values[name] = binding.object_id
        elif isinstance(binding, BatchRows):
            if any(
                k not in step.depends_on
                or binding.output not in accepted_outputs.get(k, {})
                for k, _ in binding.members
            ):
                raise ValueError("Collection requires all confirmed object outputs")
            values[name] = [
                {"object_id": obj, "value": accepted_outputs[k][binding.output]}
                for k, obj in binding.members
            ]
        elif isinstance(binding, CallerValue):
            if binding.name in caller_values:
                raw_val = caller_values[binding.name]
                values[name] = (
                    apply_projection_lens(raw_val, binding.lens)
                    if binding.lens is not None
                    else raw_val
                )
        elif isinstance(binding, LiteralValue):
            values[name] = binding.value
        elif isinstance(binding, StepValue):
            if binding.step not in step.depends_on:
                raise ValueError("Step binding is outside declared predecessors")
            if binding.step in skipped:
                if item.slot.required:
                    raise ValueError(
                        "Skipped predecessor cannot satisfy a required step input"
                    )
                continue
            outputs = _json_object(accepted_outputs[binding.step])
            if binding.output in outputs:
                raw_val = outputs[binding.output]
                values[name] = (
                    apply_projection_lens(raw_val, binding.lens)
                    if binding.lens is not None
                    else raw_val
                )
        elif isinstance(binding, CollectPack):
            packed = []
            for member in binding.items:
                if member.step not in step.depends_on:
                    raise ValueError("CollectPack member outside declared predecessors")
                if member.step in skipped:
                    if not member.allow_skipped:
                        raise ValueError(
                            f"CollectPack member {member.tag} was unexpectedly skipped"
                        )
                    packed.append(
                        {"tag": member.tag, "status": "skipped", "value": None}
                    )
                else:
                    m_out = _json_object(accepted_outputs[member.step])
                    if member.output not in m_out:
                        raise ValueError("CollectPack member missing output")
                    packed.append(
                        {
                            "tag": member.tag,
                            "status": "present",
                            "value": copy.deepcopy(m_out[member.output]),
                        }
                    )
            values[name] = packed
        else:
            raise ValueError("Unique plans do not automatically bind resources")
    return _validate_slots(
        {name: item.slot for name, item in step.inputs.items()}, values
    )


def validate_step_outputs(step: MethodStep, values: Any) -> dict:
    """Project an already validated child result into the step's output interface."""
    values = _json_object(values)
    return _validate_slots(
        step.outputs, {name: values[name] for name in step.outputs if name in values}
    )


def export_outputs(
    definition: FormalMethodDefinition,
    accepted_outputs: dict[str, dict],
    *,
    skipped_steps: Collection[str] = (),
) -> dict:
    """Validate mandatory and conditional accepted step outputs and project exports."""
    procedure = definition.procedure
    assert isinstance(procedure, Orchestration)
    skipped = set(skipped_steps)
    if procedure.has_artifact_guard or skipped:
        steps = topological_envelope_steps(procedure)
        all_ids = {s.id for s in steps}
        if (set(accepted_outputs) | skipped) != all_ids or (
            set(accepted_outputs) & skipped
        ):
            raise ValueError(
                "Envelope outputs and skipped set must partition every step"
            )
        if any(s.always_required and s.id in skipped for s in steps):
            raise ValueError("An unconditional step cannot be skipped")
        checked = {
            s.id: _validate_slots(s.outputs, accepted_outputs[s.id])
            for s in steps
            if s.id in accepted_outputs
        }
    else:
        plan = unique_plan(definition)
        if set(accepted_outputs) != {step.id for step in plan}:
            raise ValueError("Plan outputs must cover exactly every required step")
        checked = {
            step.id: _validate_slots(step.outputs, accepted_outputs[step.id])
            for step in plan
        }
    values = {
        name: checked[ref.step][ref.output]
        for name, ref in procedure.exports.items()
        if ref.step in checked and ref.output in checked[ref.step]
    }
    slots = {
        name: ValueSlot.model_validate(item["slot"])
        for name, item in definition.interfaces()["outputs"].items()
    }
    return _validate_slots(slots, values)
